import{_ as e,o as t,c as s,ag as o}from"./chunks/framework.DQQHyi2x.js";const p=JSON.parse('{"title":"Usage Tracking","description":"","frontmatter":{},"headers":[],"relativePath":"features/usage.md","filePath":"features/usage.md"}'),i={name:"features/usage.md"};function r(n,a,l,c,d,h){return t(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="usage-tracking" tabindex="-1">Usage Tracking <a class="header-anchor" href="#usage-tracking" aria-label="Permalink to &quot;Usage Tracking&quot;">​</a></h1><p>Monitor token usage, costs, and billing blocks with daily and monthly charts.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Usage page aggregates token usage data from Claude Code sessions and displays costs, trends, and billing block analysis.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="overview-tab" tabindex="-1">Overview Tab <a class="header-anchor" href="#overview-tab" aria-label="Permalink to &quot;Overview Tab&quot;">​</a></h3><p>Summary cards show total tokens, total cost, and key metrics. A daily chart plots usage over time.</p><h3 id="daily-tab" tabindex="-1">Daily Tab <a class="header-anchor" href="#daily-tab" aria-label="Permalink to &quot;Daily Tab&quot;">​</a></h3><p>Detailed daily usage and cost graphs broken down by token type:</p><ul><li><strong>Input tokens</strong> — prompt tokens sent to Claude</li><li><strong>Output tokens</strong> — response tokens from Claude</li><li><strong>Cache creation</strong> — tokens written to cache</li><li><strong>Cache read</strong> — tokens read from cache</li></ul><h3 id="sessions-tab" tabindex="-1">Sessions Tab <a class="header-anchor" href="#sessions-tab" aria-label="Permalink to &quot;Sessions Tab&quot;">​</a></h3><p>A sortable table listing individual sessions with columns for date, model, input/output tokens, and estimated cost.</p><h3 id="monthly-tab" tabindex="-1">Monthly Tab <a class="header-anchor" href="#monthly-tab" aria-label="Permalink to &quot;Monthly Tab&quot;">​</a></h3><p>Month-over-month trend charts showing usage and cost patterns.</p><h3 id="blocks-tab" tabindex="-1">Blocks Tab <a class="header-anchor" href="#blocks-tab" aria-label="Permalink to &quot;Blocks Tab&quot;">​</a></h3><p>View billing blocks — 5-hour usage windows that Anthropic uses for billing:</p><ul><li>Current active block with time remaining</li><li>Recent completed blocks with token totals and costs</li></ul><h3 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h3><p>Use the <strong>project filter</strong> dropdown to view usage for a specific project or across all projects.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Usage data is read-only. Claude Code stores usage records in:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.claude/projects/{project-folder}/usage/*.jsonl</span></span></code></pre></div><p>Claude Deck caches parsed usage data in localStorage with a 5-minute TTL for instant page loads on return visits.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li><strong>Cache tokens</strong> (creation + read) can significantly impact costs — monitor the breakdown.</li><li><strong>Billing blocks</strong> show 5-hour windows — useful for understanding burst usage patterns.</li><li>Costs are calculated using per-model, per-token-type pricing.</li><li>The page caches data client-side — click refresh for the latest numbers.</li></ul>',25)])])}const g=e(i,[["render",r]]);export{p as __pageData,g as default};
